"""specs_s200055.py - Sonnet-w2 allocator rows with a tail (generated by mkfamDT.py): the F1 fastcall hook (also records edx), the allocators (heap object or 0), INIT and the member callees record the SEH chain and vtable word; fs:[0] compared; b is zero about half of the time (class E)."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _mk(cls, f1, init, callees):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x600), rnd(c, 0x600), rnd(c, 0x600)])
        sr = seh_record(c, 2)

        def side(emu, k):
            emu.calllog.append(('edx', emu.reg('edx')))
            sr(emu, k)
        if f1:
            hook_rec(c, f1, 2, ret=r.getrandbits(32), pop=8, this=True, side=side)
        hook_rec(c, 0x45c4b0, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, 0x45c4f0, 2, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, init, 3, ret=r.getrandbits(32), pop=12, this=True, side=_side(c, p))
        for a in callees:
            hook_rec(c, a, 0, ret=r.getrandbits(32), this=True, side=_side(c, p))
        return [r.getrandbits(32), r.getrandbits(32), r.getrandbits(32), (r.choice([0, 0, 1, r.getrandbits(32)]) if cls == 'E' else r.getrandbits(32))]
    return gen


S(0x4f4e20, 'GUESS famDT 0x4f4e20', 'fastcall', None, ret='eax', gen=_mk('D', None, 0x4ee240, []), note='batch200055')
